CREATE TABLE pending_type_audit(value integer);
CREATE DOMAIN pending_positive AS integer CHECK (VALUE > 0);
CREATE TYPE pending_pair AS (id integer,label text);
CREATE FUNCTION pending_sql(value anyelement) RETURNS anyelement LANGUAGE sql VOLATILE AS 'INSERT INTO pending_type_audit VALUES (1); SELECT $1';
CREATE FUNCTION pending_pl(value anyelement) RETURNS anyelement LANGUAGE plpgsql AS $$BEGIN RETURN value; END$$;
CREATE FUNCTION pending_sql_rows(value anyelement) RETURNS SETOF anyelement LANGUAGE sql VOLATILE AS 'INSERT INTO pending_type_audit VALUES (2); SELECT $1 UNION ALL SELECT $1';
CREATE FUNCTION pending_pl_rows(value anyelement) RETURNS SETOF anyelement LANGUAGE plpgsql AS $$BEGIN RETURN NEXT value; END$$;
CREATE FUNCTION pending_record(input_value anyelement,OUT value anyelement,OUT marker integer) LANGUAGE sql VOLATILE AS 'INSERT INTO pending_type_audit VALUES (3); SELECT $1,7';
CREATE FUNCTION pending_table(input_value anyelement) RETURNS TABLE(value anyelement,marker integer) LANGUAGE sql VOLATILE AS 'INSERT INTO pending_type_audit VALUES (4); SELECT $1,8';
CREATE FUNCTION pending_named(left_value integer,right_value text DEFAULT 'fallback',OUT value integer,OUT marker text) LANGUAGE sql VOLATILE AS 'INSERT INTO pending_type_audit VALUES (5); SELECT $1,$2';
SELECT pending_sql(7),pending_sql(9::bigint),pending_sql(ARRAY[1,NULL,3]);
SELECT pending_pl(7),pending_pl(9::bigint),pending_pl(ARRAY[1,NULL,3]);
SELECT (pending_sql(ROW(1,'sql')::pending_pair)).*;
SELECT (pending_pl(ROW(2,'pl')::pending_pair)).*;
SELECT pending_sql(7::pending_positive),pending_pl(8::pending_positive);
SELECT pending_sql_rows(3);
SELECT * FROM pending_sql_rows(4);
SELECT pending_pl_rows(5);
SELECT * FROM pending_pl_rows(6);
SELECT (pending_record(7)).*;
SELECT (pending_record(ARRAY[1,NULL,3])).*;
SELECT * FROM pending_table(8);
SELECT * FROM pending_table(ARRAY[2,NULL,4]);
SELECT (pending_named(right_value=>'named',left_value=>12)).*;
SELECT (pending_named(left_value=>13)).*;
DROP FUNCTION pending_named(integer,text);
-- replacement timing
CREATE FUNCTION pending_replace(value integer) RETURNS integer LANGUAGE sql VOLATILE AS 'INSERT INTO pending_type_audit VALUES (10); SELECT $1+10';
CREATE FUNCTION pending_replace_argument() RETURNS integer LANGUAGE plpgsql AS $$BEGIN EXECUTE 'CREATE OR REPLACE FUNCTION pending_replace(value integer) RETURNS integer LANGUAGE sql VOLATILE AS ''INSERT INTO pending_type_audit VALUES (100); SELECT $1+100'''; RETURN 1; END$$;
SELECT pending_replace(pending_replace_argument());
SELECT count(*) FILTER (WHERE value=1),count(*) FILTER (WHERE value=2),count(*) FILTER (WHERE value=3),count(*) FILTER (WHERE value=4),count(*) FILTER (WHERE value=10),count(*) FILTER (WHERE value=100) FROM pending_type_audit;
DROP FUNCTION pending_replace_argument();
DROP FUNCTION pending_replace(integer);
DROP FUNCTION pending_sql(anyelement);
DROP FUNCTION pending_pl(anyelement);
DROP FUNCTION pending_sql_rows(anyelement);
DROP FUNCTION pending_pl_rows(anyelement);
DROP FUNCTION pending_record(anyelement);
DROP FUNCTION pending_table(anyelement);
DROP TYPE pending_pair;
DROP DOMAIN pending_positive;
DROP TABLE pending_type_audit;
